package glitch

import data.glitch_lib

password_keywords := {"password", "passwd", "pwd", "secret", "credential", "auth",
    "admin_password", "root_password", "master_password",
    "db_password", "database_password", "rds_password",
    "user_password", "service_password", "api_secret",
    "pass", "token", "access_key", "api_key"}

default_passwords := {"admin", "password", "123456", "default", "root", "toor",
    "guest", "user", "test", "password123", "admin123", "qwerty",
    "letmein", "welcome", "changeme", "secret", "password1"}

is_password_field(name) {
    lower_name := lower(name)
    contains(lower_name, password_keywords[_])
}

is_default_password(value) {
    lower_value := lower(value)
    default_passwords[lower_value]
}

is_literal_string(value) {
    value.ir_type == "String"
    count(value.value) > 0
    not regex.match("^\\$\\{.*\\}$", value.value)
    not regex.match("^\\{\\{.*\\}\\}$", value.value)
    not regex.match("^data\\.", value.value)
    not regex.match("^var\\.", value.value)
    not regex.match("^secret\\.", value.value)
    not regex.match("^module\\.", value.value)
    not regex.match("^aws_", value.value)
    not regex.match("^azurerm_", value.value)
    not regex.match("^google_", value.value)
}

contains_credential_in_string(str) {
    regex.match("(?i)password\\s*=\\s*[^&\\s]+", str)
} else {
    regex.match("(?i)pwd\\s*=\\s*[^&\\s]+", str)
} else {
    regex.match("(?i)://[^:]+:[^@]+@", str)
}

has_string_content(node) = value {
    walk(node, [_, n])
    n.ir_type == "String"
    value := n.value
}

check_nested_hardcoded_password(node) {
    node.ir_type == "String"
    is_literal_string(node)
    node.value != ""
    not is_variable_reference_only(node)
} else {
    node.ir_type == "Hash"
    [_, val] := node.value[_]
    check_nested_hardcoded_password(val)
} else {
    node.ir_type == "Array"
    member := node.value[_]
    check_nested_hardcoded_password(member)
}

is_variable_reference_only(node) {
    node.ir_type == "VariableReference"
}

is_variable_reference_only(node) {
    node.ir_type == "FunctionCall"
}

is_variable_reference_only(node) {
    node.ir_type == "MethodCall"
}

